function extractJsonArray(source) {
    let start = -1;
    let depth = 0;
    let inString = false;
    let escaped = false;
    for (let index = 0; index < source.length; index++) {
        const character = source[index];
        if (inString) {
            if (escaped)
                escaped = false;
            else if (character === '\\')
                escaped = true;
            else if (character === '"')
                inString = false;
            continue;
        }
        if (character === '"') {
            inString = true;
            continue;
        }
        if (character === '[') {
            if (depth === 0)
                start = index;
            depth++;
        }
        else if (character === ']' && depth > 0) {
            depth--;
            if (depth === 0 && start >= 0)
                return source.slice(start, index + 1);
        }
    }
    return null;
}
