nt-size:var(--story-font-size,17px) !important;line-height:var(--story-line-height,1.85) !important;font-family:var(--story-font-family,ui-serif,Georgia,"Songti SC",serif) !important}.modal-enter{animation:modalFadeIn .22s cubic-bezier(0.16,1,0.3,1) forwards}@keyframes modalFadeIn{from{opacity:0;transform:scale(0.98) translateY(8px)}to{opacity:1;transform:scale(1) translateY(0)}}.dock-btn{transition:all .22s cubic-bezier(0.4,0,0.2,1)}.dock-btn:hover{transform:scale(1.08) translateX(3px)}button,input,textarea,select{font-family:inherit}`, "",{"version":3,"sources":["webpack://./src/20世纪乡村生活/脚本/流式界面/style.scss"],"names":[],"mappings":"AAMA,UAEE,UAAA,CACA,WAAA,CACA,YAAA,CACA,QAAA,CACA,SAAA,CACA,eAAA,CACA,qBAAA,CAGF,qBAGE,qBAAA,CAGF,KACE,UAAA,CACA,WAAA,CACA,YAAA,CACA,eAAA,CAGF,eACE,WAAA,CACA,YAAA,CACA,UAAA,CACA,wBAAA,CACA,aAAA,CACA,iDAAA,CAIF,KACE,YAAA,CACA,6BAAA,CAIF,cACE,2BAAA,CACA,0BAAA,CACA,kCAAA,CACA,6CAAA,CAGF,cACE,2BAAA,CACA,0BAAA,CACA,kCAAA,CACA,0CAAA,CAIF,aACE,6BAAA,CACA,0BAAA,CACA,kCAAA,CAIF,oBACE,SAAA,CACA,UAAA,CAEF,0BACE,yBAAA,CAEF,0BACE,+BAAA,CACA,oBAAA,CACA,gCACE,+BAAA,CAKJ,cACE,0EAAA,CACA,sCAAA,CACA,2CAAA,CAIF,kBACE,0CAAA,CAIF,mBACE,6CAAA,CAEF,kBACE,4CAAA,CAEF,qBACE,6CAAA,CAEF,oBACE,6CAAA,CAEF,kBACE,4CAAA,CAEF,cACE,4EACE,CAKJ,YACE,gDAAA,CACA,oDAAA,CACA,kFAAA,CACA,oBAAA,CAGF,6DAGE,gDAAA,CACA,oDAAA,CACA,kFAAA,CAIF,aACE,8DAAA,CAGF,uBACE,KACE,SAAA,CACA,qCAAA,CAEF,GACE,SAAA,CACA,gCAAA,CAAA,CAKJ,UACE,6CAAA,CACA,gBACE,qCAAA,CAKJ,6BAIE,mBAAA","sourcesContent":["@use 'sass:color';\n\n/* ========================================================================= */\n/* 20世纪乡村生活 · 全局流式界面样式规范 (Global Style Tokens) */\n/* ========================================================================= */\n\nhtml,\nbody {\n  width: 100%;\n  height: 100%;\n  min-height: 0;\n  margin: 0;\n  padding: 0;\n  overflow: hidden;\n  box-sizing: border-box;\n}\n\n*,\n*::before,\n*::after {\n  box-sizing: border-box;\n}\n\n#app {\n  width: 100%;\n  height: 100%;\n  min-height: 0;\n  overflow: hidden;\n}\n\n.village-shell {\n  height: 100%;\n  min-height: 0;\n  width: 100%;\n  background-color: #030712;\n  color: #f1f5f9;\n  font-feature-settings: 'cv02', 'cv03', 'cv04', 'cv11';\n}\n\n/* 确保主小说画布能正常计算高度并触发滚动 (Main Canvas Scroll Fix) */\nmain {\n  min-height: 0;\n  overscroll-behavior-y: contain;\n}\n\n/* 玻璃拟态顶栏与底栏 (Frosted Glass Header & Footer) */\n.glass-header {\n  background: rgba(3, 7, 18, 0.88);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  border-bottom: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n.glass-bottom {\n  background: rgba(3, 7, 18, 0.92);\n  backdrop-filter: blur(16px);\n  -webkit-backdrop-filter: blur(16px);\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n/* 弹窗半透明玻璃面板 (Modal Glass Panel) */\n.glass-panel {\n  background: rgba(10, 15, 30, 0.94);\n  backdrop-filter: blur(24px);\n  -webkit-backdrop-filter: blur(24px);\n}\n\n/* 自定义纤细滚动条 (Custom Thin Scrollbar) */\n::-webkit-scrollbar {\n  width: 6px;\n  height: 6px;\n}\n::-webkit-scrollbar-track {\n  background: rgba(0, 0, 0, 0.2);\n}\n::-webkit-scrollbar-thumb {\n  background: rgba(100, 116, 139, 0.4);\n  border-radius: 9999px;\n  &:hover {\n    background: rgba(148, 163, 184, 0.6);\n  }\n}\n\n/* 角色与建档卡片通用底板 (Card Surface) */\n.card-surface {\n  background: linear-gradient(135deg, rgba(15, 23, 42, 0.85), rgba(10, 15, 30, 0.95));\n  border: 1px solid rgba(255, 255, 255, 0.08);\n  box-shadow: 0 10px 30px -10px rgba(0, 0, 0, 0.5);\n}\n\n/* 顶部与底部修饰性微渐变分割线 */\n.card-divider-top {\n  border-top: 1px solid rgba(255, 255, 255, 0.08);\n}\n\n/* 拟态光晕与弹窗阴影 (Glows & Shadows) */\n.shadow-glow-amber {\n  box-shadow: 0 0 24px -4px rgba(245, 158, 11, 0.35);\n}\n.shadow-glow-cyan {\n  box-shadow: 0 0 24px -4px rgba(6, 182, 212, 0.35);\n}\n.shadow-glow-emerald {\n  box-shadow: 0 0 24px -4px rgba(16, 185, 129, 0.35);\n}\n.shadow-glow-purple {\n  box-shadow: 0 0 24px -4px rgba(168, 85, 247, 0.35);\n}\n.shadow-glow-rose {\n  box-shadow: 0 0 24px -4px rgba(244, 63, 94, 0.35);\n}\n.shadow-modal {\n  box-shadow:\n    0 30px 80px -15px rgba(0, 0, 0, 0.95),\n    0 0 0 1px rgba(255, 255, 255, 0.08);\n}\n\n/* 正文段落排版 (Novel Text Standard · 严格绑定响应设置变量) */\n.novel-text {\n  font-size: var(--story-font-size, 17px) !important;\n  line-height: var(--story-line-height, 1.85) !important;\n  font-family: var(--story-font-family, ui-serif, Georgia, \"Songti SC\", serif) !important;\n  letter-spacing: 0.02em;\n}\n\n.novel-text p,\n.village-shell article p,\n.village-shell main p {\n  font-size: var(--story-font-size, 17px) !important;\n  line-height: var(--story-line-height, 1.85) !important;\n  font-family: var(--story-font-family, ui-serif, Georgia, \"Songti SC\", serif) !important;\n}\n\n/* 弹窗进入动画 (Modal Fade & Scale Animation) */\n.modal-enter {\n  animation: modalFadeIn 0.22s cubic-bezier(0.16, 1, 0.3, 1) forwards;\n}\n\n@keyframes modalFadeIn {\n  from {\n    opacity: 0;\n    transform: scale(0.98) translateY(8px);\n  }\n  to {\n    opacity: 1;\n    transform: scale(1) translateY(0);\n  }\n}\n\n/* 导航按钮悬浮放大微动 (Dock Button Micro-interaction) */\n.dock-btn {\n  transition: all 0.22s cubic-bezier(0.4, 0, 0.2, 1);\n  &:hover {\n    transform: scale(1.08) translateX(3px);\n  }\n}\n\n/* 基础表单元素重置 (Input Reset) */\nbutton,\ninput,\ntextarea,\nselect {\n  font-family: inherit;\n}\n"],"sourceRoot":""}]);
