const STORAGE_KEY = 'tavern_helper_assistant_api_settings_苏北乡村';
const LEGACY_STORAGE_KEYS = [
    'tavern_helper_assistant_api_settings_华北乡村',
    'tavern_helper_settings_华北乡村',
];
const DIAGNOSTIC_STORAGE_KEY = 'tavern_helper_assistant_api_diagnostics_苏北乡村';
const GOOGLE_API_URL = 'https://generativelanguage.googleapis.com/v1beta/models';
const DEEPSEEK_API_URL = 'https://api.deepseek.com';
const StoredApiSchema = z
    .object({
    id: z.string().optional(),
    apiurl: z.string().prefault(''),
    key: z.string().prefault(''),
    model: z.string().prefault(''),
    source: z.enum(['openai_compatible', 'deepseek', 'google']).prefault('openai_compatible'),
    availableModels: z.array(z.string()).prefault([]),
    sendPreset: z.boolean().prefault(false),
    collapsed: z.boolean().prefault(false),
    saved: z.boolean().prefault(false),
})
    .prefault({});
const StoredSettingsSchema = z
    .object({
    variableUpdateMode: z.enum(['with_main_api', 'extra_api']).prefault('with_main_api'),
    customApis: z.array(StoredApiSchema).optional(),
    customApi: StoredApiSchema.optional(),
})
    .prefault({});
const DiagnosticSchema = z.object({
    status: z.enum(['idle', 'running', 'success', 'failed', 'stopped', 'skipped']),
    error: z.string().prefault(''),
    at: z.string().prefault(''),
    messageId: z.number().nullable().prefault(null),
});
function createApiId() {
    return `assistant-api-${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}
function createEmptyApi() {
    return {
        id: createApiId(),
        apiurl: '',
        key: '',
        model: '',
        source: 'openai_compatible',
        availableModels: [],
        sendPreset: false,
        collapsed: false,
        saved: false,
    };
}
function normalizeApi(input, legacy = false) {
    let source = input.source;
    if (source === 'openai_compatible') {
        try {
            if (new URL(input.apiurl).hostname.toLowerCase() === 'api.deepseek.com')
                source = 'deepseek';
        }
        catch {
            // 地址合法性由保存或实际请求负责提示；这里只迁移已保存的官方 DeepSeek 地址。
        }
    }
    return {
        id: input.id || createApiId(),
        apiurl: source === 'google' ? GOOGLE_API_URL : source === 'deepseek' ? DEEPSEEK_API_URL : input.apiurl,
        key: input.key,
        model: input.model,
        source,
        availableModels: input.availableModels,
        sendPreset: input.sendPreset,
        collapsed: input.collapsed,
        saved: legacy || input.saved,
    };
}
function getStorage() {
    try {
        return window.parent?.localStorage ?? window.localStorage;
    }
    catch {
        return window.localStorage;
    }
}
function loadDiagnostics() {
    try {
        const raw = getStorage().getItem(DIAGNOSTIC_STORAGE_KEY);
        if (!raw)
            return [];
        const decoded = JSON.parse(raw);
        const list = Array.isArray(decoded) ? decoded : [decoded];
        return list.flatMap(item => {
            const parsed = DiagnosticSchema.safeParse(item);
            return parsed.success ? [parsed.data] : [];
        });
    }
    catch {
        return [];
    }
}
function sanitizeDiagnosticError(error) {
    return error
        .replace(/Bearer\s+[-A-Za-z0-9._~+/]+/gi, 'Bearer [REDACTED]')
        .replace(/([?&](?:key|api_key)=)[^&\s]+/gi, '$1[REDACTED]')
        .slice(0, 500);
}
function loadStoredSettings() {
    try {
        let raw = getStorage().getItem(STORAGE_KEY);
        if (!raw) {
            for (const legacyKey of LEGACY_STORAGE_KEYS) {
                raw = getStorage().getItem(legacyKey);
                if (raw)
                    break;
            }
        }
        const settings = StoredSettingsSchema.parse(raw ? JSON.parse(raw) : {});
        const customApis = settings.customApis?.length
            ? settings.customApis.map(api => normalizeApi(api))
            : settings.customApi && (settings.customApi.apiurl || settings.customApi.key || settings.customApi.model)
                ? [normalizeApi(settings.customApi, true)]
                : [createEmptyApi()];
        const migrated = { variableUpdateMode: settings.variableUpdateMode, customApis };
        if (!getStorage().getItem(STORAGE_KEY) && raw) {
            try {
                getStorage().setItem(STORAGE_KEY, JSON.stringify(migrated));
            }
            catch {
                console.warn('[苏北乡村][辅助API] 旧设置已读取，但暂时无法写入新的独立存储');
            }
        }
        return migrated;
    }
    catch (error) {
        console.warn('[苏北乡村][辅助API] 读取设置失败，已回退默认值');
        return { variableUpdateMode: 'with_main_api', customApis: [createEmptyApi()] };
    }
}
function validateApi(api) {
    if (!api.apiurl.trim())
        return '请填写 API 地址';
    if (!api.key.trim())
        return '请填写 API Key';
    if (!api.model.trim())
        return '请选择或填写模型';
    try {
        const url = new URL(api.apiurl);
        if (url.protocol !== 'https:')
            return 'API 地址必须使用 HTTPS';
    }
    catch {
        return 'API 地址不是合法 URL';
    }
    return null;
}
export const useAssistantApiStore = defineStore('huabei-village-assistant-api', () => {
    const stored = loadStoredSettings();
    const diagnosticHistory = ref(loadDiagnostics());
    const latestDiagnostic = diagnosticHistory.value.at(-1);
    const variableUpdateMode = ref(stored.variableUpdateMode);
    const customApis = ref(stored.customApis);
    const busy = ref(false);
    const activeMessageId = ref(null);
    const activeGenerationId = ref(null);
    const stopRequested = ref(false);
    const lastStatus = ref(latestDiagnostic?.status ?? 'idle');
    const lastError = ref(latestDiagnostic?.error ?? '');
    const lastSuccessAt = ref([...diagnosticHistory.value].reverse().find(item => item.status === 'success')?.at
        ? new Date([...diagnosticHistory.value].reverse().find(item => item.status === 'success').at).toLocaleTimeString()
        : '');
    const savedSnapshots = new Map(customApis.value.filter(api => api.saved).map(api => [api.id, _.cloneDeep(api)]));
    function persistSettings() {
        try {
            const storedApis = customApis.value
                .map(api => (api.saved ? api : savedSnapshots.get(api.id)))
                .filter((api) => Boolean(api));
            getStorage().setItem(STORAGE_KEY, JSON.stringify({
                variableUpdateMode: variableUpdateMode.value,
                customApis: storedApis,
            }));
            return true;
        }
        catch (error) {
            console.error('[苏北乡村][辅助API] 保存设置失败', error);
            return false;
        }
    }
    function runnableApis() {
        return customApis.value.filter(api => api.saved && validateApi(api) === null);
    }
    function validateAllApis() {
        const configured = customApis.value.filter(api => api.apiurl || api.key || api.model);
        if (!configured.length)
            return '请至少配置并保存一个辅助 API';
        for (const [index, api] of configured.entries()) {
            const error = validateApi(api);
            if (error)
                return `第 ${index + 1} 个辅助 API 配置不完整：${error}`;
            if (!api.saved)
                return `第 ${index + 1} 个辅助 API 尚未保存`;
        }
        return null;
    }
    function addApi() {
        customApis.value.push(createEmptyApi());
    }
    function removeApi(index) {
        if (customApis.value.length <= 1)
            return;
        const [removed] = customApis.value.splice(index, 1);
        if (removed)
            savedSnapshots.delete(removed.id);
        persistSettings();
    }
    function moveApi(index, offset) {
        const target = index + offset;
        if (target < 0 || target >= customApis.value.length)
            return;
        const [api] = customApis.value.splice(index, 1);
        customApis.value.splice(target, 0, api);
        persistSettings();
    }
    function toggleApiCollapsed(index) {
        const api = customApis.value[index];
        if (!api)
            return;
        api.collapsed = !api.collapsed;
        const snapshot = savedSnapshots.get(api.id);
        if (snapshot)
            snapshot.collapsed = api.collapsed;
        persistSettings();
    }
    function markApiDirty(apiId) {
        const api = customApis.value.find(item => item.id === apiId);
        if (api)
            api.saved = false;
    }
    function changeApiSource(apiId, source) {
        const api = customApis.value.find(item => item.id === apiId);
        if (!api)
            return;
        api.source = source;
        api.apiurl = source === 'google' ? GOOGLE_API_URL : source === 'deepseek' ? DEEPSEEK_API_URL : '';
        api.model = '';
        api.availableModels = [];
        api.saved = false;
        api.collapsed = false;
    }
    function saveApi(index) {
        const api = customApis.value[index];
        if (!api)
            return '目标 API 配置不存在';
        const error = validateApi(api);
        if (error)
            return error;
        api.apiurl = api.apiurl.trim();
        api.key = api.key.trim();
        api.model = api.model.trim();
        api.saved = true;
        api.collapsed = true;
        savedSnapshots.set(api.id, _.cloneDeep(api));
        return persistSettings() ? null : '保存失败，请检查浏览器存储权限';
    }
    async function fetchAvailableModels(index) {
        const api = customApis.value[index];
        if (!api)
            throw new Error('目标 API 配置不存在');
        if (!api.apiurl.trim())
            throw new Error('请先填写 API 地址');
        if (!api.key.trim())
            throw new Error('请先填写 API Key');
        let models;
        if (api.source === 'google') {
            const response = await fetch(`${api.apiurl}?key=${encodeURIComponent(api.key)}`);
            if (!response.ok)
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            const payload = (await response.json());
            models = (payload.models ?? [])
                .filter(model => model.supportedGenerationMethods?.includes('generateContent'))
                .map(model => model.name?.replace(/^models\//, '') ?? '')
                .filter(Boolean);
        }
        else {
            const baseUrl = api.apiurl.replace(/\/chat\/completions\/?$/i, '').replace(/\/$/, '');
            const response = await fetch(`${baseUrl}/models`, { headers: { Authorization: `Bearer ${api.key}` } });
            if (!response.ok)
                throw new Error(`HTTP ${response.status}: ${response.statusText}`);
            const payload = (await response.json());
            models = (payload.data ?? []).map(model => model.id ?? '').filter(Boolean);
        }
        const uniqueModels = _.uniq(models).sort();
        if (!uniqueModels.length)
            throw new Error('没有获取到可用模型');
        api.availableModels = uniqueModels;
        api.saved = false;
        return uniqueModels;
    }
    async function syncWorldbookMode(mode) {
        if (busy.value)
            throw new Error('辅助 API 正在运行，暂时不能切换模式');
        if (mode === 'extra_api') {
            const validationError = validateAllApis();
            if (validationError)
                throw new Error(validationError);
        }
        const worldbookName = getCharWorldbookNames('current').primary;
        if (!worldbookName)
            throw new Error('当前角色卡没有绑定主世界书');
        const entries = await getWorldbook(worldbookName);
        const previousMode = variableUpdateMode.value;
        const rules = entries.find(entry => entry.name === '[mvu_update]变量更新规则');
        const format = entries.find(entry => entry.name === '[mvu_update]变量输出格式');
        const noUpdate = entries.find(entry => entry.name === '[mvu_update]不更新变量');
        if (!rules || !format || !noUpdate)
            throw new Error('世界书缺少辅助 API 模式所需的变量条目');
        const useMainApi = mode === 'with_main_api';
        const alreadySynchronized = rules.enabled === useMainApi && format.enabled === useMainApi && noUpdate.enabled === !useMainApi;
        if (alreadySynchronized) {
            variableUpdateMode.value = mode;
            if (!persistSettings()) {
                variableUpdateMode.value = previousMode;
                throw new Error('本地设置保存失败，模式未变更');
            }
            return;
        }
        await updateWorldbookWith(worldbookName, worldbook => worldbook.map(entry => {
            if (entry.uid === rules.uid || entry.uid === format.uid)
                return { ...entry, enabled: useMainApi };
            if (entry.uid === noUpdate.uid)
                return { ...entry, enabled: !useMainApi };
            return entry;
        }));
        variableUpdateMode.value = mode;
        if (!persistSettings()) {
            await updateWorldbookWith(worldbookName, () => entries);
            variableUpdateMode.value = previousMode;
            throw new Error('本地设置保存失败，世界书模式已回滚');
        }
        const verified = await getWorldbook(worldbookName);
        const verify = (name) => verified.find(entry => entry.name === name)?.enabled;
        if (verify('[mvu_update]变量更新规则') !== useMainApi ||
            verify('[mvu_update]变量输出格式') !== useMainApi ||
            verify('[mvu_update]不更新变量') === useMainApi) {
            await updateWorldbookWith(worldbookName, () => entries);
            variableUpdateMode.value = previousMode;
            persistSettings();
            throw new Error('世界书模式回读不一致，已回滚');
        }
    }
    async function reconcileWorldbookMode() {
        try {
            await syncWorldbookMode(variableUpdateMode.value);
        }
        catch (error) {
            console.warn('[苏北乡村][辅助API] 初始化模式同步失败', error);
            finishRun('failed', error instanceof Error ? `模式同步失败：${error.message}` : '模式同步失败');
            if (variableUpdateMode.value === 'extra_api') {
                variableUpdateMode.value = 'with_main_api';
                persistSettings();
                try {
                    await syncWorldbookMode('with_main_api');
                }
                catch (fallbackError) {
                    console.error('[苏北乡村][辅助API] 回退主模型模式失败', fallbackError);
                }
            }
        }
    }
    function beginRun(messageId, generationId) {
        busy.value = true;
        activeMessageId.value = messageId;
        activeGenerationId.value = generationId;
        stopRequested.value = false;
        lastStatus.value = 'running';
        lastError.value = '';
    }
    function finishRun(status, error = '') {
        const finishedMessageId = activeMessageId.value;
        busy.value = false;
        activeMessageId.value = null;
        activeGenerationId.value = null;
        stopRequested.value = false;
        lastStatus.value = status;
        lastError.value = sanitizeDiagnosticError(error);
        if (status === 'success')
            lastSuccessAt.value = new Date().toLocaleTimeString();
        try {
            const diagnostics = {
                status,
                error: lastError.value,
                at: new Date().toISOString(),
                messageId: finishedMessageId,
            };
            diagnosticHistory.value = [...diagnosticHistory.value, diagnostics].slice(-20);
            getStorage().setItem(DIAGNOSTIC_STORAGE_KEY, JSON.stringify(diagnosticHistory.value));
        }
        catch {
            console.warn('[苏北乡村][辅助API] 脱敏诊断记录保存失败');
        }
    }
    async function setVariableUpdateMode(mode) {
        await syncWorldbookMode(mode);
    }
    function clearAllCredentials() {
        customApis.value = [createEmptyApi()];
        savedSnapshots.clear();
        persistSettings();
        try {
            getStorage().removeItem(LEGACY_STORAGE_KEY);
        }
        catch {
            console.warn('[苏北乡村][辅助API] 旧凭据副本清理失败');
        }
    }
    return {
        variableUpdateMode,
        customApis,
        busy,
        activeMessageId,
        activeGenerationId,
        stopRequested,
        lastStatus,
        lastError,
        lastSuccessAt,
        diagnosticHistory,
        runnableApis,
        validateAllApis,
        addApi,
        removeApi,
        moveApi,
        toggleApiCollapsed,
        markApiDirty,
        changeApiSource,
        saveApi,
        fetchAvailableModels,
        syncWorldbookMode,
        reconcileWorldbookMode,
        beginRun,
        finishRun,
        persistSettings,
        setVariableUpdateMode,
        clearAllCredentials,
    };
});
