import { klona } from 'klona';
import { Schema, type Schema as StatData } from '../../schema';
import { migrateLegacyState } from '../../stateMigration';
import { normalizeStateTransition, type NormalizeStateTransitionOptions } from '../../stateValidation';
import { useAssistantApiStore } from './assistantApiStore';
import { deleteAvatar } from './avatarStore';

let queue: Promise<void> = Promise.resolve();
let transactionGeneration = 0;

type WritableState = {
  targetMessageId: number;
  chatId: string;
  generation: number;
  target: { type: 'message'; message_id: number };
  targetMvu: Mvu.MvuData;
  targetVariables: Record<string, unknown>;
  data: StatData;
};

function currentChatId(): string {
  return String(SillyTavern.getCurrentChatId?.() ?? '');
}

function assertTargetCurrent(state: Pick<WritableState, 'chatId' | 'generation'>): void {
  if (state.generation !== transactionGeneration || state.chatId !== currentChatId()) {
    throw new Error('聊天已切换或界面已卸载，当前事务已安全取消');
  }
}

function runtimeGenerating(): boolean {
  const tavern = SillyTavern as typeof SillyTavern & {
    isGenerating?: boolean;
    getContext?: () => { isGenerating?: boolean };
  };
  return Boolean(tavern.isGenerating || tavern.getContext?.()?.isGenerating);
}

function assertIdle(): void {
  if (runtimeGenerating() || useAssistantApiStore().busy) throw new Error('变量更新运行期间暂不能执行此操作');
}

async function latestState(): Promise<WritableState> {
  await waitGlobalInitialized('Mvu');
  const targetMessageId = getLastMessageId();
  if (targetMessageId < 0) throw new Error('当前聊天没有可写入楼层');
  const target = { type: 'message', message_id: targetMessageId } as const;
  const targetMvu = klona(Mvu.getMvuData(target));
  const targetVariables = klona(getVariables(target));
  const chatId = currentChatId();
  const generation = transactionGeneration;

  for (let sourceMessageId = targetMessageId; sourceMessageId >= 0; sourceMessageId--) {
    const source = Mvu.getMvuData({ type: 'message', message_id: sourceMessageId });
    const raw = _.get(source, 'stat_data');
    if (_.isEmpty(raw)) continue;
    const parsed = Schema.safeParse(migrateLegacyState(raw));
    if (parsed.success) return { targetMessageId, chatId, generation, target, targetMvu, targetVariables, data: parsed.data };
  }

  const chatRaw = _.get(Mvu.getMvuData({ type: 'chat' }), 'stat_data');
  const chatParsed = Schema.safeParse(migrateLegacyState(chatRaw));
  if (!_.isEmpty(chatRaw) && chatParsed.success) return { targetMessageId, chatId, generation, target, targetMvu, targetVariables, data: chatParsed.data };
  throw new Error('找不到任何可用的MVU状态，操作已停止');
}

async function rollback(state: WritableState): Promise<void> {
  if (state.chatId !== currentChatId() || state.generation !== transactionGeneration) {
    console.warn('[苏北乡村] 聊天已切换或界面已卸载，已阻止失效事务回滚');
    return;
  }
  const failures: unknown[] = [];
  try {
    await Mvu.replaceMvuData(klona(state.targetMvu), state.target);
  } catch (error) {
    failures.push(error);
  }
  try {
    replaceVariables(klona(state.targetVariables), state.target);
  } catch (error) {
    failures.push(error);
  }
  if (failures.length) console.error('[苏北乡村] MVU事务回滚未完全成功');
}

async function write(
  state: WritableState,
  nextInput: unknown,
  options: NormalizeStateTransitionOptions = {},
): Promise<void> {
  const next = normalizeStateTransition(state.data, nextInput, options);
  const mvu = klona(state.targetMvu);
  const variables = klona(state.targetVariables);
  _.set(mvu, 'stat_data', next);
  _.set(variables, 'stat_data', next);
  try {
    assertTargetCurrent(state);
    await Mvu.replaceMvuData(mvu, state.target);
    assertTargetCurrent(state);
    replaceVariables(variables, state.target);
    assertTargetCurrent(state);
    const mvuSaved = Schema.safeParse(migrateLegacyState(_.get(Mvu.getMvuData(state.target), 'stat_data')));
    const variableSaved = Schema.safeParse(migrateLegacyState(_.get(getVariables(state.target), 'stat_data')));
    if (
      !mvuSaved.success ||
      !variableSaved.success ||
      !_.isEqual(mvuSaved.data, next) ||
      !_.isEqual(variableSaved.data, next)
    ) {
      throw new Error('写入后双重校验失败');
    }
  } catch (error) {
    await rollback(state);
    throw error;
  }
}

function enqueue<T>(operation: () => Promise<T>): Promise<T> {
  const result = queue.then(operation, operation);
  queue = result.then(
    () => undefined,
    () => undefined,
  );
  return result;
}

export function savePlayerProfile(
  profile: Pick<StatData['玩家信息'], '姓名' | '性别' | '年龄' | '身份' | '性格' | '外貌' | '背景'>,
): Promise<void> {
  return enqueue(async () => {
    assertIdle();
    const state = await latestState();
    const next = klona(state.data);
    Object.assign(next.玩家信息, profile);
    next.系统状态.初始化状态 = '档案已保存';
    await write(state, next, { allowPlayerProfileEdit: true });
  });
}

export function setInitializationState(
  status: Extract<StatData['系统状态']['初始化状态'], '等待首轮剧情' | '等待变量更新' | '失败'>,
  error = '',
): Promise<void> {
  return enqueue(async () => {
    const state = await latestState();
    const next = klona(state.data);
    next.系统状态.初始化状态 = status;
    next.系统状态.初始化事务ID ||= `init:${Date.now()}:${Math.random().toString(36).slice(2, 9)}`;
    next.系统状态.初始化错误 = status === '失败' ? error.slice(0, 500) : '';
    await write(state, next, { allowSystemLifecycleUpdate: true });
  });
}

export function purchaseProduct(name: string): Promise<string> {
  return enqueue(async () => {
    assertIdle();
    const state = await latestState();
    const next = klona(state.data);
    const item = next.系统商店.商品[name];
    if (!item || item.库存 <= 0) throw new Error('商品已售罄');
    if (next.玩家信息.人民币 < item.价格) throw new Error('人民币不足');
    next.玩家信息.人民币 -= item.价格;
    item.库存 -= 1;
    const owned = next.玩家信息.物品栏[name];
    if (owned) {
      owned.数量 += 1;
      Object.assign(owned, {
        分类: item.分类,
        可使用: item.可使用,
        使用后消耗: item.使用后消耗,
        介绍: item.介绍,
        物品ID: owned.物品ID || `shop:${name}`,
        取得来源: '系统商店购买',
        最近成交价: item.价格,
      });
    }
    else
      next.玩家信息.物品栏[name] = {
        分类: item.分类,
        可使用: item.可使用,
        使用后消耗: item.使用后消耗,
        数量: 1,
        介绍: item.介绍,
        物品ID: `shop:${name}`,
        取得来源: '系统商店购买',
        最近成交价: item.价格,
      };
    await write(state, next, { allowLocalInventoryTransaction: true });
    return `已购买「${name}」`;
  });
}

export function requestShopRefresh(): Promise<void> {
  return enqueue(async () => {
    assertIdle();
    const state = await latestState();
    if (state.data.玩家信息.人民币 < 100) throw new Error('人民币不足100元');
    if (state.data.系统商店.待刷新) return;
    const next = klona(state.data);
    next.玩家信息.人民币 -= 100;
    next.系统商店.待刷新 = true;
    await write(state, next, { allowShopRefreshRequest: true });
  });
}

export function deleteCharacter(roleId: number): Promise<{ avatarCleanupFailed: boolean }> {
  return enqueue(async () => {
    assertIdle();
    const state = await latestState();
    const next = klona(state.data);
    const id = String(roleId);
    const deletedRole = next.角色信息[id];
    if (!deletedRole) throw new Error('角色不存在');
    delete next.角色信息[id];
    delete next.玩家信息.手机.通讯录[id];
    Object.values(next.角色信息).forEach(role => delete role.关系网[id]);
    next.玩家信息.手机.短信记录 = next.玩家信息.手机.短信记录.filter(record => record.联系人 !== deletedRole.姓名);
    await write(state, next, { allowLocalCharacterDelete: true });
    try {
      await deleteAvatar(roleId);
      return { avatarCleanupFailed: false };
    } catch {
      console.warn('[苏北乡村] 角色已删除，但本地头像清理失败');
      return { avatarCleanupFailed: true };
    }
  });
}

export function requestCharacterPromotion(roleId: number): Promise<void> {
  return enqueue(async () => {
    assertIdle();
    const state = await latestState();
    const id = String(roleId);
    const role = state.data.普通角色[id];
    if (!role) throw new Error('普通角色已不存在');
    if (role.待升阶) return;
    const next = klona(state.data);
    next.普通角色[id].待升阶 = true;
    await write(state, next, { allowPromotionRequestIds: [id] });
  });
}

export function appendSmsRecord(record: {
  联系人: string;
  发送方: '玩家' | '对方';
  内容: string;
  时间: string;
}): Promise<void> {
  return enqueue(async () => {
    assertIdle();
    const state = await latestState();
    const next = klona(state.data);
    if (!next.玩家信息.手机.短信记录) next.玩家信息.手机.短信记录 = [];
    next.玩家信息.手机.短信记录.push(record);
    await write(state, next, { allowSmsTransaction: true });
  });
}

export function requestItemUse(name: string): Promise<void> {
  return enqueue(async () => {
    assertIdle();
    const state = await latestState();
    const item = state.data.玩家信息.物品栏[name];
    if (!item?.可使用) throw new Error('该物品当前不可使用');
    const pending = state.data.玩家信息.待处理物品使用;
    if (pending.物品名称 && pending.物品名称 !== name) throw new Error(`请先处理待使用物品「${pending.物品名称}」`);
    const next = klona(state.data);
    next.玩家信息.待处理物品使用 = { 物品名称: name, 请求楼层: state.targetMessageId };
    await write(state, next, { allowItemUseRequest: true });
  });
}

export function cancelPendingMvuActions(): void {
  transactionGeneration += 1;
  queue = Promise.resolve();
}
